toml = "0.5.11"
colored = "2.0.0"
itertools = "0.13.0"
serde-big-array = "0.5.1"
num-bigint = { version = "0.4.4", features = ["rand"] }
ark-std = { version = "0.5.0", default-features = false, features = ["print-trace"] }
ark-crypto-primitives = { version = "0.5.0", features = ["snark", "sponge"] }
ark-relations = "0.5.0"
serial_test = "*"
tqdm = "0.7"
secp256k1 = { version = "0.29.1", features = ["global-context"]}
derive_more = "2.0"

[profile.dev]
opt-level = 3

[profile.release]
lto = true

manifests.package.json:
{
  "name": "virtual-scroll",
  "version": "2.2.1",
  "description": "Custom scroll events for smooth, fake scroll",
  "main": "lib/virtualscroll.js",
  "source": "src/index.js",
  "scripts": {
    "build": "microbundle build -i src/index.js --format umd --compress --no-sourcemap --no-pkg-main --external none",
    "test": "browserify test/index.js | smokestack | faucet",
    "test-debug": "budo test/index.js --live"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/ayamflow/virtual-scroll"
  },
  "keywords": [
    "virtual",
    "scroll",
    "smooth"
  ],
  "author": "Florian Morel",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/ayamflow/virtual-scroll/issues"
  },
  "homepage": "https://github.com/ayamflow/virtual-scroll",
  "dependencies": {
    "tiny-emitter": "^2.1.0"
  },
  "devDependencies": {
    "browserify": "^14.3.0",
    "budo": "^9.4.7",
    "faucet": "0.0.1",
    "microbundle": "^0.13.0",
    "smokestack": "^3.4.1",
    "tape": "^4.6.3",
    "tiny-trigger": "scottcorgan/tiny-trigger"
  }
}

